<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>جست‌وجو | سینماپلاس</title><link rel="stylesheet" href="/css/cinema.css"></head><body><header class="nav"><a class="brand" href="/"><img src="/images/branding/cinemaplus-logo.png" alt="سینماپلاس" style="height:52px;width:52px;object-fit:contain;vertical-align:middle"><span>سینماپلاس</span></a></header><main class="container"><h1>جست‌وجوی فیلم، تئاتر و کنسرت</h1><form class="search" style="margin:20px 0;width:100%"><input class="field" name="q" value="{{ request('q') }}" placeholder="نام اثر یا توضیحات"><select class="field" name="type"><option value="">همه انواع</option><option value="cinema" @selected(request('type')==='cinema')>سینما</option><option value="theater" @selected(request('type')==='theater')>تئاتر</option><option value="concert" @selected(request('type')==='concert')>کنسرت</option></select><select class="field" name="category"><option value="">همه دسته‌ها</option>@foreach($categories as $category)<option value="{{ $category->id }}" @selected((string)request('category')===(string)$category->id)>{{ $category->name }}</option>@endforeach</select><select class="field" name="city"><option value="">همه شهرها</option>@foreach($cities as $city)<option value="{{ $city }}" @selected(request('city')===$city)>{{ $city }}</option>@endforeach</select><input class="field" type="date" name="date" value="{{ request('date') }}"><button class="primary">جست‌وجو</button></form><div class="grid">@forelse($events as $event)<a class="card" href="{{ route('events.show',$event) }}"><div class="poster">{{ $event->title }}</div><div class="cardbody"><b>{{ $event->title }}</b><p>{{ $event->summary }}</p></div></a>@empty<p>نتیجه‌ای پیدا نشد.</p>@endforelse</div>{{ $events->links() }}</main></body></html>
